package it.attendance100.mybicocca.codegen.target.kotlin

import it.attendance100.mybicocca.codegen.core.GeneratedFile
import it.attendance100.mybicocca.codegen.core.resourceFiles

/**
 * The runtime every API generated by [KotlinTarget] builds on: the base class of the modules, the
 * HTTP client and its settings, the policy describing an API's errors and retries, the files
 * multipart forms upload, and the base exception. [KotlinTarget] writes it once per output
 * directory as its shared files, so that the SDK holds only generated code.
 *
 * The sources are this module's `kotlin-runtime` resources, with their package set to the APIs'
 * `runtimePackage`.
 */
internal object KotlinRuntime {
    private const val PACKAGE_PLACEHOLDER = "__PACKAGE__"
    private val FILES = listOf("ApiException.kt", "FileUpload.kt", "RestApi.kt", "RestClient.kt", "RestPolicy.kt")

    fun files(packageName: String): List<GeneratedFile> =
        resourceFiles(javaClass, "kotlin-runtime", FILES, packageName.replace('.', '/')) { it.replace(PACKAGE_PLACEHOLDER, packageName) }
}
